#!/usr/bin/env node
/**
 * 打包 preview-ui 为单文件 IIFE，并生成供 prdGenerator 内联的 .generated.ts。
 * 运行: node scripts/build-preview-ui-prd-bundle.mjs
 * 产物: scripts/preview-ui-prd-bundle.js, src/lib/preview-ui-prd-bundle.generated.ts
 */
import * as esbuild from 'esbuild';
import { readFileSync, writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, '..');
const outFile = join(root, 'scripts', 'preview-ui-prd-bundle.js');
const generatedPath = join(root, 'src', 'lib', 'preview-ui-prd-bundle.generated.ts');

await esbuild.build({
  entryPoints: [join(__dirname, 'entry-preview-ui-prd.ts')],
  bundle: true,
  format: 'iife',
  globalName: 'PRDPreviewUI',
  platform: 'browser',
  target: 'es2018',
  alias: {
    react: join(__dirname, 'react-global-shim.js'),
    'react-dom': join(__dirname, 'react-dom-global-shim.js'),
  },
  outfile: outFile,
});

let code = readFileSync(outFile, 'utf8');
// IIFE 会得到 (function(react, reactDom) { ... })(react, reactDom); 需要改为接收全局 React
// esbuild 的 iife + external 会生成 factory(require('react')) 之类的，需确认
// 实际输出可能是 var PRDPreviewUI = (function(){ ... return init; })(); 且内部用 globalThis.React
// 我们改为：不 external，把 react 作为参数传入。这样 IIFE 是 (function(React, ReactDOM){ ... })(?)
// 用 inject 注入 React 从 window 取：不适用。还是 external，然后输出后我们包一层 (function(){ ... })(window.React, window.ReactDOM)
// 将 bundle 转成可嵌入模板字符串的字面量（供 .generated.ts 使用）
const escaped = code
  .replace(/\\/g, '\\\\')
  .replace(/`/g, '\\`')
  .replace(/\$/g, '\\$');
const generated = `/** Generated by scripts/build-preview-ui-prd-bundle.mjs - do not edit */
export const PREVIEW_UI_PRD_BUNDLE = \`${escaped}\`;
export const PREVIEW_UI_PRD_BUNDLE_CALL = 'if (typeof PRDPreviewUI !== "undefined") { var __fn = typeof PRDPreviewUI === "function" ? PRDPreviewUI : (PRDPreviewUI && PRDPreviewUI.default); if (typeof __fn === "function") __fn(window.React); }';
`;

mkdirSync(dirname(generatedPath), { recursive: true });
writeFileSync(generatedPath, generated, 'utf8');
console.log('Wrote', generatedPath);
console.log('Bundle size:', (code.length / 1024).toFixed(1), 'KB');
